from pathlib import Path
p=Path('/app/static/app.js')
s=p.read_text()
router_old="const titles={overview:'Overview',traders:'Trader universe','multi-trader':'Multi-Trader Mode',history:'Trade behaviour',reports:'Reports & exports',data:'Data import',system:'Source & system'};$('#page-title').textContent=titles[name]||name;if(name==='traders')loadTraders();if(name==='multi-trader')loadMultiTrader(false);if(name==='history')loadPaths();if(name==='system')loadSystem();"
router_new="const titles={overview:'Overview',traders:'Trader universe','multi-trader':'Multi-Trader Mode','portfolio-lab':'Portfolio Lab',history:'Trade behaviour',reports:'Reports & exports',data:'Data import',system:'Source & system'};$('#page-title').textContent=titles[name]||name;if(name==='traders')loadTraders();if(name==='multi-trader')loadMultiTrader(false);if(name==='portfolio-lab')loadPortfolioLab();if(name==='history')loadPaths();if(name==='system')loadSystem();"
if "if(name==='portfolio-lab')loadPortfolioLab();" not in s:
    if s.count(router_old)!=1: raise RuntimeError("page router anchor not unique")
    s=s.replace(router_old,router_new,1)
js=r'''
// PORTFOLIO_LAB_UI_V1
let pl={market:'FUTURES',portfolios:[],ranked:[],unready:[],selected:null,offset:0,limit:100,forecast:[]};
function plNum(id,def){const raw=$(id).value;const v=Number(raw);return raw!==''&&Number.isFinite(v)?v:def}
function plInputs(){return {market_type:$('#pl-market').value,investment:plNum('#pl-capital',250),allocation_pct:plNum('#pl-allocation',10),extra_cost_bps:plNum('#pl-cost-bps',5),days:Number($('#pl-horizon').value||7)}}
function plUsd(v){return v===null||v===undefined||v===''||!Number.isFinite(Number(v))?'—':Number(v).toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2})}
function plPct(v){return v===null||v===undefined||v===''||!Number.isFinite(Number(v))?'—':Number(v).toFixed(2)+'%'}
function plTime(ms){if(ms===null||ms===undefined||ms==='')return '—';const d=new Date(Number(ms));return Number.isNaN(d.getTime())?'—':d.toLocaleString('en-GB',{timeZone:'UTC',hour12:false})+' UTC'}
function plLink(url){return typeof url==='string'&&url.startsWith('https://www.binance.com/')?'<a target="_blank" rel="noopener noreferrer" href="'+esc(url)+'">Official Binance page ↗</a>':'Official link unavailable'}
function plRenderPortfolios(){const rows=pl.portfolios;$('#pl-profile-meta').textContent=rows.length+' stored · '+pl.market;$('#pl-profile-rows').innerHTML=rows.length?rows.map(t=>'<tr><td><b>'+esc(t.nickname||'Unknown')+'</b><small style="display:block;color:#8c98a8">'+esc(t.market_type)+' · '+esc(t.portfolio_id||'')+'</small></td><td>'+plLink(t.profile_url)+'</td><td>'+plPct(t.roi)+'</td><td>'+plPct(t.mdd)+'</td><td>'+plPct(t.win_rate)+'</td><td>'+Number(t.stored_positions||0)+'</td><td>'+Number(t.with_mae_mfe||0)+' / '+Number(t.stored_positions||0)+'</td><td>'+esc(t.history_status||'unknown')+'</td><td><button class="icon-button" data-pl-id="'+Number(t.id)+'">Inspect</button></td></tr>').join(''):'<tr><td colspan="9" class="empty-state">'+(pl.market==='SPOT'?'No Spot profiles are stored. The current collector has not yet validated a working Spot source.':'No stored portfolios found.')+'</td></tr>';$$('[data-pl-id]').forEach(b=>b.addEventListener('click',()=>plLoadPortfolio(Number(b.dataset.plId),0)))}
function plRankRow(t,ranked){return '<tr><td>'+(ranked?t.forecast_rank:'—')+'</td><td><b>'+esc(t.nickname||'Unknown')+'</b><small style="display:block">'+esc(t.portfolio_id||'')+'</small>'+plLink(t.profile_url)+'</td><td>'+plUsd(t.expected_horizon_profit_usd)+'</td><td>'+plUsd(t.median_horizon_profit_usd)+'</td><td>'+plUsd(t.p10_horizon_profit_usd)+' / '+plUsd(t.p90_horizon_profit_usd)+'</td><td>'+(t.observed_median_leverage===null?'—':Number(t.observed_median_leverage).toFixed(2)+'×')+'</td><td>'+plUsd(t.historical_modelled_profit_usd)+'</td><td>'+plUsd(t.historical_modelled_max_drawdown_usd)+'</td><td>'+Number(t.forecastable_trades||0)+'</td><td><button class="icon-button" data-pl-id="'+Number(t.id)+'">Inspect</button></td></tr>'}
async function plRunForecast(){const q=new URLSearchParams(plInputs());$('#pl-rank-note').textContent='Calculating from stored closed trades. Portfolios without enough evidence will not get a made-up return estimate.';$('#pl-rank-rows').innerHTML='<tr><td colspan="10" class="empty-state">Running forecast…</td></tr>';try{const d=await api('/api/portfolio-lab/forecast?'+q.toString());pl.ranked=d.ranked||[];pl.unready=d.insufficient_history||[];$('#pl-rank-meta').textContent=d.forecastable_count+' forecastable · '+d.insufficient_history_count+' insufficient';$('#pl-rank-note').textContent='Ranked by expected '+d.horizon_days+'-day hypothetical PnL after '+d.extra_copy_cost_bps+' bps additional copy-drag assumption on notional; investment $'+Number(d.investment_usd).toFixed(2)+', allocated margin '+d.allocation_per_position_pct+'% per position. '+d.forecast_method;$('#pl-rank-rows').innerHTML=pl.ranked.length?pl.ranked.map(t=>plRankRow(t,true)).join(''):'<tr><td colspan="10" class="empty-state">No portfolio meets the evidence threshold. No forward ranking was fabricated.</td></tr>';$('#pl-unready-rows').innerHTML=pl.unready.length?pl.unready.map(t=>'<tr><td><b>'+esc(t.nickname||'Unknown')+'</b><small style="display:block">'+plLink(t.profile_url)+'</small></td><td>'+Number(t.forecastable_trades||0)+'</td><td>'+plPct(t.source_roi)+'</td><td>'+esc(t.evidence_gap||'Insufficient history')+'</td><td><button class="icon-button" data-pl-id="'+Number(t.id)+'">Inspect</button></td></tr>').join(''):'<tr><td colspan="5" class="empty-state">No insufficient profiles.</td></tr>';$$('[data-pl-id]').forEach(b=>b.addEventListener('click',()=>plLoadPortfolio(Number(b.dataset.plId),0)));if(pl.selected){const found=pl.ranked.concat(pl.unready).find(t=>Number(t.id)===Number(pl.selected));pl.forecast=found?found.forecast_days||[]:[]}plRenderDailyForecast();}catch(e){$('#pl-rank-note').textContent='Forecast failed: '+e.message;$('#pl-rank-rows').innerHTML='<tr><td colspan="10" class="empty-state">'+esc(e.message)+'</td></tr>'}}
function plRenderDailyForecast(){const rows=pl.forecast||[];$('#pl-daily-forecast').innerHTML=rows.length?rows.map(x=>'<tr><td>Day '+x.day+'</td><td>'+plUsd(x.expected_pnl_usd)+'</td><td>'+plUsd(x.median_pnl_usd)+'</td><td>'+plUsd(x.p10_pnl_usd)+'</td><td>'+plUsd(x.p90_pnl_usd)+'</td><td>'+plPct(x.expected_return_pct)+'</td></tr>').join(''):'<tr><td colspan="6" class="empty-state">No reliable daily estimate for this profile yet.</td></tr>'}
function plDrawCurve(points){const c=$('#pl-curve');if(!c)return;const x=c.getContext('2d');const w=c.width=Math.max(600,c.clientWidth*2),h=c.height=440;x.clearRect(0,0,w,h);x.strokeStyle='#294052';for(let i=1;i<=4;i++){x.beginPath();x.moveTo(35,i*h/5);x.lineTo(w-20,i*h/5);x.stroke()}if(!points||points.length<2){x.fillStyle='#9db0c3';x.font='26px sans-serif';x.fillText('Not enough recorded closes to draw a curve',35,70);return}const v=points.map(p=>Number(p.cumulative_realized_pnl)||0),lo=Math.min(0,...v),hi=Math.max(0,...v),r=Math.max(1,hi-lo);x.strokeStyle='#65e5b7';x.lineWidth=4;x.beginPath();v.forEach((n,i)=>{const px=35+i/(v.length-1)*(w-55),py=h-30-(n-lo)/r*(h-65);i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke();x.fillStyle='#b8c8d7';x.font='22px sans-serif';x.fillText('Cumulative closed PnL · last $'+v[v.length-1].toFixed(2),35,26)}
function plRenderBehavior(b){const rows=[['Closed records',b.closed_pnl_records],['Closed-trade win rate',plPct(b.closed_trade_win_rate_pct)],['Profit factor',b.profit_factor==='INF'?'∞':(b.profit_factor===null?'—':Number(b.profit_factor).toFixed(2))],['Average win',plUsd(b.average_win)],['Average loss',plUsd(b.average_loss)],['Largest loss',plUsd(b.largest_loss)],['Median leverage',b.median_observed_leverage===null?'—':Number(b.median_observed_leverage).toFixed(2)+'×'],['Maximum leverage',b.max_observed_leverage===null?'—':Number(b.max_observed_leverage).toFixed(2)+'×'],['Average MAE',plPct(b.average_mae_pct)],['Average MFE',plPct(b.average_mfe_pct)]];$('#pl-behaviour').innerHTML=rows.map(p=>'<div><b>'+esc(p[0])+'</b><p>'+esc(String(p[1]===null||p[1]===undefined?'—':p[1]))+'</p></div>').join('')}
async function plLoadPortfolio(id,offset=0){pl.selected=id;pl.offset=offset;const q=new URLSearchParams({...plInputs(),offset,limit:pl.limit});$('#pl-detail-title').textContent='Loading portfolio…';try{const d=await api('/api/portfolio-lab/portfolio/'+id+'?'+q.toString());const t=d.profile,c=d.coverage;$('#pl-detail-title').textContent=(t.nickname||'Portfolio')+' · '+t.portfolio_id;$('#pl-official-link').innerHTML=plLink(t.profile_url)+' · last stored refresh '+esc(t.last_seen||'unknown');$('#pl-kpi-trades').textContent=c.stored_positions;$('#pl-kpi-paths').textContent=c.with_mae_mfe+' / '+c.stored_positions;$('#pl-kpi-pnl').textContent=plUsd(d.curve.net_recorded_closed_pnl);$('#pl-kpi-dd').textContent=plUsd(d.curve.max_drawdown_from_cumulative_realized_peak_usd);plRenderBehavior(d.behavior);plDrawCurve(d.curve.points);$('#pl-snapshot-rows').innerHTML=d.snapshots.length?d.snapshots.map(s=>'<tr><td>'+esc(s.captured_at||'—')+'</td><td>'+esc(s.time_range||'—')+'</td><td>'+plPct(s.roi)+'</td><td>'+plUsd(s.pnl)+'</td><td>'+plPct(s.mdd)+'</td><td>'+plPct(s.win_rate)+'</td><td>'+plUsd(s.copier_pnl)+'</td></tr>').join(''):'<tr><td colspan="7" class="empty-state">No source snapshots stored.</td></tr>';$('#pl-trade-coverage').textContent=c.with_mae_mfe+' trades have MAE/MFE; '+c.path_analyzed+' paths analysed; '+c.missing_close_timestamp+' lack a close timestamp. Missing close time does not prove a live position.';const sc={};(d.scenario_trades||[]).forEach(v=>sc[v.position_id]=v);$('#pl-trade-rows').innerHTML=d.trades.length?d.trades.map(v=>{const z=sc[v.id]||{};return '<tr><td>'+plTime(v.closed_ms)+'<small style="display:block">'+esc(v.close_status)+'</small></td><td>'+esc(v.symbol||'—')+'</td><td>'+esc(v.side||'—')+'</td><td>'+plTime(v.opened_ms)+'<small style="display:block">'+(v.entry_price===null?'—':Number(v.entry_price).toPrecision(7))+'</small></td><td>'+(v.exit_price===null?'—':Number(v.exit_price).toPrecision(7))+'</td><td>'+(v.leverage===null?'—':Number(v.leverage).toFixed(2)+'×')+'</td><td>'+esc(v.margin_mode||'—')+'</td><td>'+plUsd(v.close_pnl)+'</td><td>'+plPct(v.roi_pct)+'</td><td>'+plPct(v.mae_pct)+'</td><td>'+plPct(v.mfe_pct)+'</td><td>'+((v.time_to_mae_min===null?'—':Number(v.time_to_mae_min).toFixed(0)+'m')+' / '+(v.time_to_mfe_min===null?'—':Number(v.time_to_mfe_min).toFixed(0)+'m'))+'</td><td>'+esc(v.path_status||'NOT_ANALYZED')+'</td><td>'+plUsd(z.hypothetical_pnl_usd)+'</td></tr>'}).join(''):'<tr><td colspan="14" class="empty-state">No position rows stored for this portfolio.</td></tr>';const end=Math.min(d.trade_total,d.trade_offset+d.trade_limit);$('#pl-trades-page').textContent=(d.trade_total?d.trade_offset+1:0)+'–'+end+' of '+d.trade_total+' records';$('#pl-trades-prev').disabled=d.trade_offset<=0;$('#pl-trades-next').disabled=end>=d.trade_total;$('#pl-model-notes').textContent=d.open_position_note+' Scenario illustration uses $'+plNum('#pl-capital',250)+' investment and '+plNum('#pl-allocation',10)+'% margin allocation per trade; individual position estimates do not account for overlapping capital use.';const f=pl.ranked.concat(pl.unready).find(v=>Number(v.id)===Number(id));pl.forecast=f?f.forecast_days||[]:[];plRenderDailyForecast()}catch(e){$('#pl-detail-title').textContent='Portfolio data unavailable';$('#pl-model-notes').textContent=e.message}}
async function loadPortfolioLab(){pl.market=$('#pl-market').value;try{const d=await api('/api/portfolio-lab/portfolios?market_type='+pl.market);pl.portfolios=d.items||[];plRenderPortfolios();if(!pl.portfolios.length&&pl.market==='SPOT')$('#pl-rank-note').textContent='Spot is empty because no Spot portfolio rows are stored. The current collector’s Spot source still needs validation; this page will not invent Spot data.';if(pl.selected&&pl.portfolios.some(t=>Number(t.id)===Number(pl.selected)))await plLoadPortfolio(pl.selected,pl.offset);else pl.selected=null;}catch(e){$('#pl-profile-rows').innerHTML='<tr><td colspan="9" class="empty-state">'+esc(e.message)+'</td></tr>'}}
$('#pl-run-forecast').addEventListener('click',plRunForecast);$('#pl-refresh').addEventListener('click',async()=>{await loadPortfolioLab();await plRunForecast()});$('#pl-market').addEventListener('change',async()=>{pl.selected=null;await loadPortfolioLab();await plRunForecast()});$('#pl-trades-prev').addEventListener('click',()=>pl.selected&&plLoadPortfolio(pl.selected,Math.max(0,pl.offset-pl.limit)));$('#pl-trades-next').addEventListener('click',()=>pl.selected&&plLoadPortfolio(pl.selected,pl.offset+pl.limit));
'''
if "PORTFOLIO_LAB_UI_V1" not in s:
    if s.count("async function loadSystem(){")!=1: raise RuntimeError("Portfolio Lab UI anchor not unique")
    s=s.replace("async function loadSystem(){",js+"\nasync function loadSystem(){",1)
p.write_text(s)
print("Portfolio Lab UI installed")
